def generate_primes(n):
    if n < 2:
        return []
    is_prime_array = [True] * (n + 1)
    is_prime_array[0], is_prime_array[1] = False, False
    for i in range(2, n+1):
        if is_prime_array[i]:
            k = 2 * i
            while k < n + 1:
                is_prime_array[k] = False
                k += i
    return list(filter(lambda i: is_prime_array[i], range(n+1)))


