    def dijkstra(s, n):
        hq = [(0, s)]
        heapq.heapify(hq)  # リストを優先度付きキューに変換
        cost = [float('inf')] * n  # 行ったことのないところはinf
        cost[s] = 0  # 開始地点は0
        while hq:
