            if c > cost[v]:  # コストが現在のコストよりも高ければスルー
                continue
            for d, u in e[v]:
                tmp = d + cost[v]
                if tmp < cost[u]:
                    cost[u] = tmp
                    heapq.heappush(hq, (tmp, u))
        return cost



