def rle(l):
    ret = []
    n = len(l)
    cnt = 1
    for i in range(1,n):
        if l[i - 1] == l[i]:
            cnt+=1
        else:
            ret.append([l[i - 1],cnt])
            cnt = 1
        if i == n - 1:
            ret.append([l[i],cnt])
    return ret

