    if arr is None:
      self.roots = [-1 for i in range(N)]
      self.ranks = [0 for i in range(N)]
    else:
      self.roots = arr[:]
      self.ranks = [0 for i in range(N)]

  def root(self, i):
    root = self.roots[i]
    if root < 0:
      return i
    else:
      return self.root(root)

  def union(self, i, j):
    x = self.root(i)
    y = self.root(j)
    if x == y:
      return
    if self.ranks[x] < self.ranks[y]:
      self.roots[x] = y
    else:
      self.roots[y] = x
      if self.ranks[x] == self.ranks[y]:
        self.ranks[x] += 1

  def same(self, i, j):
    return self.root(i) == self.root(j)

  def get_rank(self, i):
