import sys

def solve(N: int, A: "List[int]"):
    ans, t, s = 0, 0, 0
    for h in range(N):
        while t < N and s ^ A[t] == s + A[t]:
            s += A[t]
            t += 1
        ans += t - h
        s -= A[h]
    return ans

