def dijkstra(G, start):
    n = len(G)
    dist = [float("inf")]*n
    visited = set()
    heap = []
    heap.append((0, start))

    while heap and len(visited) != n:
        d, cur = heappop(heap)
        if cur in visited:
            continue
        visited.add(cur)
        dist[cur] = d
        for to in range(10):
            if to not in visited:
                heappush(heap, (d+G[cur][to], to))
    return dist

