        target = 0
        min_val = MAX
        for i in visited:
            for j in un_visited:
                if costs[j][i] < min_val:
                    min_val = costs[j][i]
                    target = j

        visited.add(target)
        un_visited.remove(target)
        to_ones[target] = min_val

        for x in un_visited:
            costs[x][target] += min_val

    A_cnts = [0] * 11 # -1 -> 10

