def dijkstra(S,N,cost):
	d = [float("inf")]*N
	used = [False]*N
	d[S] = 0

	while True:
		v = -1
		for i in range(N):
			if (not used[i]) and (v == -1):
				v = i
			elif (not used[i]) and d[i] < d[v]:
				v = i
		if v == -1:
			break
		used[v] = True

		for j in range(N):
			d[j] = min(d[j], d[v]+cost[v][j])

	return d

