    h,w = LI()
    a = [input() for i in range(h)]
    d = defaultdict(lambda : 0)
    for i in a:
        for j in i:
            d[j] += 1
    l = []
    s = deque()
    for i in d.keys():
        if d[i]&1:
            l.append(i)
        elif d[i]&3:
            s.append(i)
    if len(l) > 1:
        print("No")
        return

