def bubble_sort(A):
    cnt = 0
    flag = True
    while flag:
        flag = False
        for i in sorted(range(1, len(A)), reverse=True):
            if A[i] < A[i - 1]:
                cnt += 1
                tmp = A[i]
                A[i] = A[i - 1]
                A[i - 1] = tmp
                flag = True
    return A, cnt


def selection_sort(A):
    for i in range(len(A)):
        minj = i
        for j in range(i, len(A)):
            if A[j] < A[minj]:
                minj = j
        tmp = A[i]
        A[i] = A[minj]
        A[minj] = tmp
    return A


