def egcd(a: int, b: int):
    """extended gcd"""
    if a == 0:
        return b, 0, 1
    else:
        g, y, x = egcd(b % a, a)
        return g, x - (b // a) * y, y


def mod_inv(a, mod=10**9 + 7):
    """mod inversion """
    g, x, y = egcd(a, mod)
    if g != 1:
        raise Exception('modular inverse does not exist')
    else:
        return x % mod


def mod_combination(n, r, mod=10**9 + 7) -> int:
    r = min(r, n - r)
    res = 1
    for i in range(r):
        res = res * (n - i) * mod_inv(i + 1, mod) % mod
    return res


