def solve():
    N = Scanner.int()
    A = Scanner.map_int()
    S = sum(A)
    X = [0 for _ in range(N)]

    for i in range(1, N, 2):
        X[0] -= 2 * A[i]
    X[0] += S

    for i in range(1, N):
        X[i] = 2 * A[i - 1] - X[i - 1]
    print(*X)


