def ep(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.perf_counter()
        ret = f(*args, **kwargs)
        e = time.perf_counter()

        ep(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, K, AB):
    g = defaultdict(list)
    for a, b in AB:
        g[a].append(b)
        g[b].append(a)

    s = [(1, -1, 0, 0)]
    ans = [1] * (N+1)
    while s:
        u, p, k1, k2 = s.pop()
        ans[u] = K - k1 - k2

        cu = 0
        for v in g[u]:
            if v == p:
                continue
            s.append((v, u, 1, cu+k1))
            cu += 1

    M = 10**9+7
    return reduce(lambda x, y: (x * y) % M, ans)



