def answer_is_X(X):
    mod = deque(sorted([i%X for i in A if i%X != 0]))
    answer = 0
    while mod:
        Amin = mod.popleft()
        answer += Amin
        while Amin > 0:
            # ポップできない場合
            if not mod:
                return False
            Amax = mod.pop()
            sub = X - Amax
            if sub <= Amin:
                Amin -= sub
            else:
                Amax += Amin
                mod.append(Amax)
                Amin = 0

    if answer <= K:
        return True
    else:
        return False

