    for i in reversed(range(n)):
        R_rev_acc[i]=R_rev_acc[i+1]+R_rev[i]
    tmp=float('inf')
    for i in range(n+1):
        tmp=min(tmp,max(R_acc[i],R_rev_acc[i]))
    return tmp<=k

