    tmp = [0 for i in range(r+l)]
    if (r+l)%2==0:
        tmp[r-1]=(r+l)//2
        tmp[r]=(r+l)//2
    else:
        if r%2==0:
            tmp[r-1]=(r+l)//2
            tmp[r]=(r+l)//2+1
        else:
            tmp[r-1]=(r+l)//2+1
            tmp[r]=(r+l)//2
    return tmp

