def myAnswer(N:int,T:int,t:list) -> int:
   total = T*N
   sub = 0
   if(N == 1): return T
   pre = t.pop(0)
   for time in t:
      if(pre + T - time > 0):
         sub += pre+T - time
      pre = time
   return total - sub

