def slv(N, C):
    C_ = [-1]
    for c in C:
        if C_[-1] == c:
            continue
        C_.append(c)

    C = C_

    mod = 10**9 + 7
    S = defaultdict(lambda: 0)
    ans = 1
    for c in C:
        ans = (ans + S[c]) % mod
        S[c] = ans

    return ans


