    """
    １からの遷移に分解する系の発想なのかなあ
    table[s][t] = (sスタートでtエンドの列車本数)
    として２次元テーブルを用意しておけば、クエリ(p, q)に対する解は
        sum(table[ps:q][p:q])
    で彫られ、これは２次元累積和で高速計算可能。
    """

    table = [[0] * N for _ in range(N)]
    for _ in range(M):
        l, r = map(int, input().split())
