def g(n: int):
    # 0 1 11 00 100 001 111 000 1000 0001 1011 0000 1100 0001 1111 0000
    # 0110
    # 0010
    # 00001010
    # 0000000010101010

    ans = 0
    ans += [0, 1, 1, 0][n % 4]
    for i in range(1, 64):
        k = n % 2 ** (i + 1)
        if k < 2 ** i:
