        if S[i] == 'C':
            cnt += 1
            C = i
    if cnt != 1:
        return 'WA'
    T = S[:C] + S[C+1:]
    Tset = set(list(T[1:]))
    sletter = set(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'])
    if sletter.union(Tset) != sletter:
        return 'WA'
    return 'AC'


