def solve(A, nNow, n, m, q, a, b, c, d):
    if nNow == n:
        ret = 0
        for i in range(q):
            if A[b[i] - 1] - A[a[i] - 1] == c[i]:
                ret += d[i]
        return ret
    elif nNow == 0:
        ret = 0
        for i in range(1, m + 1):
            ret = max(ret, solve(A + [i], nNow + 1, n, m, q, a, b, c, d))
        return ret
    else:
        ret = 0
        for i in range(A[nNow - 1], m + 1):
            ret = max(ret, solve(A + [i], nNow + 1, n, m, q, a, b, c, d))
        return ret


