    C = [[0] * 51 for _ in range(51)]
    for i in range(N + 1):
        for j in range(i + 1):
            if j == 0 or i == j:
                C[i][j] = 1
            else:
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j]
    return C


