class UnionFind():
    def __init__(self, n):
        self.n = n
        self.parent = list(range(n))
        self.rank = [1] * n
        self.grp = n

    def root(self,x):
        if self.parent[x] == x :
            return x
        else :
            self.parent[x] = self.root(self.parent[x])
            return self.parent[x]

    def same(self,x,y):
        return self.root(x) == self.root(y)

    def unite(self,x,y):
        x = self.root(x)
        y = self.root(y)

        if x == y:
            return
        if self.rank[x] < self.rank[y]:
            self.parent[x] = y
        else :
            self.parent[y] = x
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1
        self.grp -= 1


