def calc_cost(li):
    """
    与えられた部分リストが各アルゴリズムの条件を
    満たすか確認し、そのコストを計算。
    条件満たさないときは100000000を出力
    """

    # flag = True
    cost = 0
    for item in li:
        cost += item[0]

    for i in range(M):
        algo_sum = 0
        for item in li:
            algo_sum += item[i + 1]
        if algo_sum < X:
            return 100000000

    return cost


