def parse(s):
    "バランスしていない閉じ括弧数, 開き括弧数"
    cl, op = 0, 0
    for c in s:
        if c == '(':
            op += 1
        elif op > 0:
            op -= 1
        else:
            cl += 1
    return (cl, op)

inc   = []  # 開き括弧が多い
dec   = []  # 閉じ括弧が多い
close = []  # 閉じ括弧のみ
