def count(s):
    m=0
    e=0
    for t in s:
        if t=='(':
            e+=1
        else:
            e-=1
            m=min(m,e)
    return (e,m)
def count_reverse(s):
    m=0
    e=0
    for t in s[::-1]:
        if t==')':
            e+=1
        else:
            e-=1
            m=min(m,e)
    return (e,m)

def main():
