def read_int():
    return int(input().strip())


def read_ints():
    return list(map(int, input().strip().split(' ')))


def merge_sort(A):
    N = len(A)
    if N < 2:
        return A, 0
    mid = N//2
    left, left_count = merge_sort(A[:mid])
    right, right_count = merge_sort(A[mid:])
    total_count = left_count+right_count
    lowers = 0
    answer = []
    for l in left:
        while lowers < len(right) and right[lowers] < l:
            answer.append(right[lowers])
            lowers += 1
        total_count += lowers
        answer.append(l)
    while lowers < len(right):
        answer.append(right[lowers])
        lowers += 1
    return answer, total_count


def solve():
    N, K = read_ints()
    A = read_ints()
    _, left_greater = merge_sort(A)
    _, right_greater = merge_sort(A[::-1])
    modulo = 10**9+7
    return (K*(K+1)//2*left_greater+K*(K-1)//2*right_greater)%modulo


if __name__ == '__main__':
    print(solve())

import sys

readline = sys.stdin.readline
MOD = 10 ** 9 + 7
INF = float('INF')
sys.setrecursionlimit(10 ** 5)


class BinaryIndexTree:
    def __init__(self, n):
        self.size = n
        self._container = [0] * (n + 1)
        self.depth = n.bit_length()

    def sum(self, i):
        if i == 0:
            return 0
        s = 0
        while i > 0:
            s += self._container[i]
            i -= i & (-i)
        return s

    def add(self, i, x):
        if i == 0:
            return
        while i <= self.size:
            self._container[i] += x
            i += i & (-i)

    def lower_bound(self, x):
        if x == 0:
            return 0

        s = 0
        idx = 0
        for i in range(self.depth, -1, -1):
            k = idx + (1 << i)
            if k <= self.size and s + self._container[k] < x:
                s += self._container[k]
                idx += 1 << i
        return idx + 1

    def __repr__(self):
        return str(self._container)


def main():
    n, k = map(int, readline().split())
    a = list(map(int, readline().split()))
    bit = BinaryIndexTree(2000)

    p = 0
    q = 0
    for x in a[::-1]:
        p += bit.sum(x - 1)
        bit.add(x, 1)

    for i in range(2, 2001):
        q += (bit.sum(i) - bit.sum(i - 1)) * bit.sum(i - 1)

    ans = p * k + q * (k - 1) * k // 2
    print(ans % MOD)


if __name__ == '__main__':
    main()

