    is_prime = [True] * (n+1)
    is_prime[0] = False
    is_prime[1] = False

    p = 0
    for i in range(2,n+1):
        if is_prime[i]:
            p = i
            for j in range(p+p, n+1, p):
                is_prime[j] = False

        if p * p > n:
            break

    primes = []
    for i in range(2,n+1):
        if is_prime[i]:
            primes.append(i)

    return primes

